import type { InvoiceTemplate } from '@invoice-generator/shared-types'

/**
 * System Templates - Available to ALL users
 *
 * These templates are:
 * - Static (defined in code, not localStorage)
 * - Protected (cannot be deleted or modified)
 * - Distinguished by isSystem: true
 *
 * Design principles (Vercel-inspired):
 * - Monochrome palette (black/white/gray)
 * - Clean typography hierarchy
 * - Minimal borders, subtle dividers
 * - Grid-aligned elements
 * - Professional, modern enterprise feel
 *
 * Positioning Notes:
 * - A4 page: 595.28 x 841.89 pts
 * - With 50pt margins on all sides, content area: 495pt x 742pt
 * - Full content width: 495pt
 * - All elements positioned within 0-495pt width range
 * - Right-aligned elements: x + width <= 495
 */

// System template IDs (prefixed to avoid collision with user templates)
export const SYSTEM_TEMPLATE_IDS = {
  // Classic templates (absolute positioning)
  CLASSIC_LIGHT: 'system-classic-light',
  CLASSIC_DARK: 'system-classic-dark',
  VERCEL_MINIMAL: 'system-vercel-minimal',
  VERCEL_PROFESSIONAL: 'system-vercel-professional',
  VERCEL_EXECUTIVE: 'system-vercel-executive',
  VERCEL_MODERN: 'system-vercel-modern',
  VERCEL_CLASSIC: 'system-vercel-classic',
  DARK_NOIR: 'system-dark-noir',
  MIDNIGHT_BLUE: 'system-midnight-blue',
  CARBON_TERMINAL: 'system-carbon-terminal',
  OBSIDIAN_ELEGANCE: 'system-obsidian-elegance',
  // V2 templates (container-based layout)
  CLASSIC_LIGHT_V2: 'system-classic-light-v2',
  CLASSIC_DARK_V2: 'system-classic-dark-v2',
  VERCEL_MINIMAL_V2: 'system-vercel-minimal-v2',
  VERCEL_PROFESSIONAL_V2: 'system-vercel-professional-v2',
  VERCEL_EXECUTIVE_V2: 'system-vercel-executive-v2',
  VERCEL_MODERN_V2: 'system-vercel-modern-v2',
  VERCEL_CLASSIC_V2: 'system-vercel-classic-v2',
  DARK_NOIR_V2: 'system-dark-noir-v2',
  MIDNIGHT_BLUE_V2: 'system-midnight-blue-v2',
  CARBON_TERMINAL_V2: 'system-carbon-terminal-v2',
  OBSIDIAN_ELEGANCE_V2: 'system-obsidian-elegance-v2',
} as const

// The default system template ID
